/*
 * 7-Segment Counter — display digits 0..9
 * Segments a–g on D2..D8, common cathode to GND
 */

int segPins[7] = {2, 3, 4, 5, 6, 7, 8};

// Segment masks for digits 0..9 (a=MSB ... g=LSB)
byte digits[10] = {
  0b1111110, // 0
  0b0110000, // 1
  0b1101101, // 2
  0b1111001, // 3
  0b0110011, // 4
  0b1011011, // 5
  0b1011111, // 6
  0b1110000, // 7
  0b1111111, // 8
  0b1111011  // 9
};

void setup() {
  for (int i = 0; i < 7; i++) pinMode(segPins[i], OUTPUT);
  Serial.begin(115200);
  Serial.println("7-segment counter started");
}

void showDigit(int d) {
  for (int i = 0; i < 7; i++) {
    digitalWrite(segPins[i], (digits[d] >> (6 - i)) & 1 ? HIGH : LOW);
  }
}

void loop() {
  for (int d = 0; d <= 9; d++) {
    showDigit(d);
    Serial.print("Count: ");
    Serial.println(d);
    delay(500);
  }
}
